EXECUTE 'SET LOCAL ROLE service_role';
SELECT * INTO STRICT r FROM public.stellar_create_phone_support_test_intake('5885a020-d363-4c27-910a-c035eda132f5'::uuid,'phone-staging:CAd0f60a38f0824e738793c4be3b5a907e','Fictional staging customer','gateway-f082e736-793c-4be3-b5a9-907e657556a2@example.invalid','','Synthetic staging router','2026-10-01'::date,'Fictional staging gateway acceptance; no real customer or notification.','gateway-f082e736-793c-4be3-b5a9-907e657556a2','No real business affected','NORMAL');
