GET DIAGNOSTICS n=ROW_COUNT;IF n<>1 THEN RAISE EXCEPTION 'WORKFLOW_COUNT_INVALID';END IF;
IF (SELECT count(*) FROM public.stellar_support_cases)<>21 OR (SELECT count(*) FROM public.ai4cc_contacts)<>14 OR EXISTS(SELECT 1 FROM public.stellar_support_cases WHERE intake_session_id='phone-staging:CAaf4db9fd72404d28ac4c3b128173fb7a') OR EXISTS(SELECT 1 FROM public.stellar_orchestrator_events_staging) OR EXISTS(SELECT 1 FROM public.stellar_dispatch_receipts_staging) OR EXISTS(SELECT 1 FROM public.stellar_dispatch_effects_staging) THEN RAISE EXCEPTION 'FIXTURE_COUNTS_INVALID';END IF;
IF (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.stellar_support_cases c WHERE id<>r.case_id)<>'ddeb4729999cd8a90965ab2197b4355c' OR (SELECT md5(coalesce(string_agg(to_jsonb(c)::text,'' ORDER BY id),'')) FROM public.ai4cc_contacts c WHERE id<>r.customer_id)<>'a67f355fc8bc1a3e258ab772b308c485' THEN RAISE EXCEPTION 'ORIGINAL_ROWS_CHANGED';END IF;
