SELECT now() observed_at,w.*,c.contact_id,c.intake_session_id case_session,k.email,md5(to_jsonb(w)::text) workflow_hash,md5(to_jsonb(c)::text) case_hash,md5(to_jsonb(k)::text) contact_hash FROM public.stellar_orchestrator_workflows_staging w JOIN public.stellar_support_cases c ON c.id=w.case_id JOIN public.ai4cc_contacts k ON k.id=c.contact_id WHERE w.workflow_id='d0f60a38-f082-4e73-8793-c4be3b5a907e';

